using SAUDICO.Federate.Core;using SAUDICO.Federate.Shared;using Xunit;namespace SAUDICO.Federate.Tests;public sealed class ExportSettingsTests{[Fact]public void FrozenDefaults(){var s=ExportSettings.Default();Assert.False(s.ExportLinks);Assert.True(s.DivideLevels);Assert.True(s.ElementIds);Assert.True(s.Properties);Assert.Equal(ParamMode.All,s.Parameters);Assert.Equal(CoordMode.Shared,s.Coordinates);Assert.True(s.ExModelLines);Assert.False(s.Overwrite);Assert.True(s.Log);Assert.True(s.Csv);}[Fact]public void SnapshotIsIndependent(){var a=ExportSettings.Default();var b=a.Copy();b.DivideLevels=false;Assert.True(a.DivideLevels);}}